const items = $input.all();
const isEmpty = !items || items.length === 0 || (items.length === 1 && (!items[0].json || Object.keys(items[0].json).length === 0));
if (isEmpty) {
  const wanted = $('Config').first().json['Channel Name'];
  throw new Error(`No channel found named "${wanted}". Check spelling/casing against the channels table.`);
}
const channel = items[0].json;
if (!channel.youtube_channel_id) {
  throw new Error('This channel has no youtube_channel_id set. Complete YOUTUBE-OAUTH-SETUP.md step 7 first.');
}
const today = new Date();
const end = today.toISOString().slice(0, 10);
const startDate = new Date(today);
startDate.setUTCDate(today.getUTCDate() - 30);
const start = startDate.toISOString().slice(0, 10);
return [{ json: { channel_id: channel.id, name: channel.name, youtube_channel_id: channel.youtube_channel_id, start_date: start, end_date: end, snapshot_date: end } }];

const resp = $input.first().json;
const headers = (resp.columnHeaders || []).map(h => h.name);
const rows = resp.rows || [];
if (rows.length === 0) {
  throw new Error('YouTube Analytics returned no rows for this channel in the last 30 days. Either nothing has been published yet (see Phase 10), or it is too early for data to appear (YouTube Analytics typically lags 1-2 days behind real time).');
}
const idx = name => headers.indexOf(name);
const parsed = rows.map(row => ({
  youtube_video_id: row[idx('video')],
  views: row[idx('views')],
  likes: row[idx('likes')],
  comments: row[idx('comments')],
  avg_view_duration_seconds: row[idx('averageViewDuration')],
  retention_pct: row[idx('averageViewPercentage')],
  subscribers_gained: row[idx('subscribersGained')],
  impressions: row[idx('impressions')],
  ctr: row[idx('impressionsClickThroughRate')]
}));
return parsed.map(p => ({ json: p }));

const items = $input.all();
const ids = items.map(i => i.json.youtube_video_id).filter(Boolean);
return [{ json: { youtube_ids_filter: `in.(${ids.map(id => `"${id}"`).join(',')})` } }];

const map = $input.all().map(i => i.json).filter(v => v && v.youtube_video_id);
const byYoutubeId = Object.fromEntries(map.map(v => [v.youtube_video_id, v.id]));
const report = $('Parse Analytics Report').all().map(i => i.json);
const snapshotDate = $('Pick Channel Row').first().json.snapshot_date;

const rows = [];
const skipped = [];
for (const r of report) {
  const internalId = byYoutubeId[r.youtube_video_id];
  if (!internalId) { skipped.push(r.youtube_video_id); continue; }
  rows.push({
    video_id: internalId,
    snapshot_date: snapshotDate,
    impressions: r.impressions ?? null,
    ctr: r.ctr ?? null,
    avg_view_duration_seconds: r.avg_view_duration_seconds ?? null,
    retention_pct: r.retention_pct ?? null,
    likes: r.likes ?? null,
    comments: r.comments ?? null,
    subscribers_gained: r.subscribers_gained ?? null
  });
}
if (rows.length === 0) {
  throw new Error(`YouTube Analytics returned data for ${report.length} video(s), but none matched a videos.youtube_video_id in this database (skipped: ${skipped.join(', ')}). They were likely uploaded outside this pipeline.`);
}
return [{ json: { rows, skipped_count: skipped.length } }];

const built = $('Build Snapshot Rows').first().json;
return [{ json: {
  result: `${built.rows.length} analytics_snapshots rows inserted for ${$('Pick Channel Row').first().json.name}.`,
  skipped_videos_not_in_db: built.skipped_count
} }];
